H.rect(cx - halfL, cy - rad, 2 * halfL, 2 * rad, { stroke: H.colors.grid, width: 1, radius: 6 });
for (let k = 0; k < turns; k++) {
  const x = cx - halfL + (2 * halfL) * (k + 0.5) / turns;
  H.circle(x, cy - rad, 7, { stroke: H.colors.accent2, width: 2 });
  H.circle(x, cy + rad, 7, { stroke: H.colors.accent2, width: 2 });
