  H.text(I >= 0 ? "x" : ".", x, cy - rad, { color: H.colors.accent2, size: 9, align: "center", baseline: "middle" });
  H.text(I >= 0 ? "." : "x", x, cy + rad, { color: H.colors.accent2, size: 9, align: "center", baseline: "middle" });
